CREATE TABLE el_portal_links(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,user_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('student','guardian','teacher')),student_id TEXT,guardian_id TEXT,teacher_id TEXT,is_demo INTEGER NOT NULL DEFAULT 0,created_by TEXT NOT NULL REFERENCES el_users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,user_id),CHECK((kind='student' AND student_id IS NOT NULL AND guardian_id IS NULL AND teacher_id IS NULL) OR (kind='guardian' AND guardian_id IS NOT NULL AND student_id IS NULL AND teacher_id IS NULL) OR (kind='teacher' AND teacher_id IS NOT NULL AND student_id IS NULL AND guardian_id IS NULL)),FOREIGN KEY(org_id,user_id) REFERENCES el_memberships(org_id,user_id),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id),FOREIGN KEY(org_id,guardian_id) REFERENCES el_guardians(org_id,id),FOREIGN KEY(org_id,teacher_id) REFERENCES el_teachers(org_id,id));
CREATE UNIQUE INDEX el_portal_link_student ON el_portal_links(org_id,student_id) WHERE student_id IS NOT NULL;
CREATE UNIQUE INDEX el_portal_link_guardian ON el_portal_links(org_id,guardian_id) WHERE guardian_id IS NOT NULL;
CREATE UNIQUE INDEX el_portal_link_teacher ON el_portal_links(org_id,teacher_id) WHERE teacher_id IS NOT NULL;
CREATE TABLE el_lessons(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,group_id TEXT NOT NULL,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',kind TEXT NOT NULL CHECK(kind IN ('article','video','live','material')),content TEXT NOT NULL DEFAULT '',url TEXT NOT NULL DEFAULT '',position INTEGER NOT NULL DEFAULT 0,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','archived')),published_at INTEGER,is_demo INTEGER NOT NULL DEFAULT 0,created_by TEXT NOT NULL REFERENCES el_users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),FOREIGN KEY(org_id,group_id) REFERENCES el_groups(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TABLE el_lesson_progress(org_id TEXT NOT NULL,lesson_id TEXT NOT NULL,student_id TEXT NOT NULL,completed_at INTEGER NOT NULL,is_demo INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(lesson_id,student_id),FOREIGN KEY(org_id,lesson_id) REFERENCES el_lessons(org_id,id),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id));
CREATE TABLE el_assignments(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,group_id TEXT NOT NULL,title TEXT NOT NULL,instructions TEXT NOT NULL,due_at INTEGER NOT NULL,max_score INTEGER NOT NULL CHECK(max_score BETWEEN 1 AND 10000),status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','closed')),is_demo INTEGER NOT NULL DEFAULT 0,created_by TEXT NOT NULL REFERENCES el_users(id),created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),FOREIGN KEY(org_id,group_id) REFERENCES el_groups(org_id,id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TABLE el_submissions(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,assignment_id TEXT NOT NULL,student_id TEXT NOT NULL,body TEXT NOT NULL,url TEXT NOT NULL DEFAULT '',score INTEGER,feedback TEXT NOT NULL DEFAULT '',graded_by TEXT REFERENCES el_users(id),submitted_at INTEGER NOT NULL,graded_at INTEGER,is_demo INTEGER NOT NULL DEFAULT 0,UNIQUE(org_id,id),UNIQUE(assignment_id,student_id),FOREIGN KEY(org_id,assignment_id) REFERENCES el_assignments(org_id,id),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id));
CREATE TRIGGER el_submission_insert_guard BEFORE INSERT ON el_submissions BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_assignments a JOIN el_enrollments en ON en.group_id=a.group_id AND en.student_id=NEW.student_id AND en.status='active' WHERE a.id=NEW.assignment_id AND a.org_id=NEW.org_id AND a.status='published' AND a.due_at>=NEW.submitted_at) THEN RAISE(ABORT,'Assignment is closed, overdue or student is not enrolled') END;END;
CREATE TRIGGER el_submission_update_guard BEFORE UPDATE ON el_submissions BEGIN SELECT CASE WHEN NEW.body<>OLD.body OR NEW.url<>OLD.url OR NEW.student_id<>OLD.student_id OR NEW.assignment_id<>OLD.assignment_id OR NEW.submitted_at<>OLD.submitted_at THEN RAISE(ABORT,'Submitted work is immutable') END;SELECT CASE WHEN NEW.score IS NOT NULL AND (NEW.score<0 OR NEW.score>(SELECT max_score FROM el_assignments WHERE id=OLD.assignment_id)) THEN RAISE(ABORT,'Submission score exceeds assignment maximum') END;END;
CREATE TABLE el_discussions(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,group_id TEXT NOT NULL,user_id TEXT NOT NULL,body TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'visible' CHECK(status IN ('visible','hidden')),is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),FOREIGN KEY(org_id,group_id) REFERENCES el_groups(org_id,id),FOREIGN KEY(org_id,user_id) REFERENCES el_memberships(org_id,user_id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE TABLE el_portal_requests(id TEXT PRIMARY KEY,org_id TEXT NOT NULL,branch_id TEXT NOT NULL,student_id TEXT NOT NULL,user_id TEXT NOT NULL,kind TEXT NOT NULL CHECK(kind IN ('absence_excuse','meeting','contact')),subject TEXT NOT NULL,body TEXT NOT NULL,requested_on TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','accepted','rejected','closed')),response TEXT NOT NULL DEFAULT '',decided_by TEXT REFERENCES el_users(id),is_demo INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(org_id,id),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id),FOREIGN KEY(org_id,user_id) REFERENCES el_memberships(org_id,user_id),FOREIGN KEY(org_id,branch_id) REFERENCES el_branches(org_id,id));
CREATE INDEX el_lessons_group ON el_lessons(org_id,group_id,status,position);
CREATE INDEX el_progress_student ON el_lesson_progress(org_id,student_id,lesson_id);
CREATE INDEX el_assignments_group ON el_assignments(org_id,group_id,status,due_at);
CREATE INDEX el_submissions_assignment ON el_submissions(org_id,assignment_id,student_id);
CREATE INDEX el_discussions_group ON el_discussions(org_id,group_id,status,created_at);
CREATE INDEX el_portal_requests_student ON el_portal_requests(org_id,student_id,status);
CREATE INDEX el_portal_requests_branch ON el_portal_requests(org_id,branch_id,status);
ALTER TABLE el_exam_results ADD COLUMN grading_source TEXT NOT NULL DEFAULT 'manual';
ALTER TABLE el_exam_results ADD COLUMN submitted_by TEXT REFERENCES el_users(id);
CREATE TABLE el_quiz_attempts(org_id TEXT NOT NULL,exam_id TEXT NOT NULL,student_id TEXT NOT NULL,submitted_at INTEGER NOT NULL,is_demo INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(exam_id,student_id),FOREIGN KEY(org_id,exam_id) REFERENCES el_exams(org_id,id),FOREIGN KEY(org_id,student_id) REFERENCES el_students(org_id,id));

CREATE TRIGGER el_assignment_lock BEFORE UPDATE ON el_assignments WHEN EXISTS(SELECT 1 FROM el_submissions WHERE assignment_id=OLD.id) BEGIN SELECT CASE WHEN NEW.title<>OLD.title OR NEW.instructions<>OLD.instructions OR NEW.max_score<>OLD.max_score OR NEW.group_id<>OLD.group_id OR NEW.status='draft' THEN RAISE(ABORT,'Submitted work locks assignment content') END; END;
CREATE TRIGGER el_quiz_answer_lock BEFORE UPDATE ON el_exam_answers WHEN EXISTS(SELECT 1 FROM el_quiz_attempts WHERE exam_id=OLD.exam_id AND student_id=OLD.student_id) BEGIN SELECT CASE WHEN NEW.answer<>OLD.answer OR NEW.student_id<>OLD.student_id OR NEW.question_id<>OLD.question_id OR NEW.exam_id<>OLD.exam_id THEN RAISE(ABORT,'Submitted work is immutable') END; END;
CREATE TRIGGER el_quiz_open_guard BEFORE INSERT ON el_quiz_attempts BEGIN SELECT CASE WHEN NOT EXISTS(SELECT 1 FROM el_exams e JOIN el_enrollments en ON en.group_id=e.group_id AND en.org_id=e.org_id AND en.student_id=NEW.student_id AND en.status='active' WHERE e.org_id=NEW.org_id AND e.id=NEW.exam_id AND e.status='published' AND e.scheduled_at<=NEW.submitted_at) THEN RAISE(ABORT,'Assignment is closed or student is not enrolled') END; END;

ALTER TABLE el_announcements ADD COLUMN group_id TEXT REFERENCES el_groups(id);
CREATE INDEX el_announcements_group ON el_announcements(org_id,group_id,created_at);

CREATE TRIGGER el_portal_request_decision_guard BEFORE UPDATE ON el_portal_requests BEGIN SELECT CASE WHEN OLD.status<>'pending' OR NEW.status NOT IN ('accepted','rejected','closed') OR NEW.student_id<>OLD.student_id OR NEW.user_id<>OLD.user_id OR NEW.body<>OLD.body OR NEW.subject<>OLD.subject THEN RAISE(ABORT,'Leave decision requires a pending request') END; END;
